    "text": "De acuerdo con el artículo 39.2 de la Ley 1/83, las Direcciones Generales y las Secretarías Generales Técnicas podrán organizarse a su vez en Subdirecciones Generales y otras unidades administrativas inferiores. Las denominaciones de estas últimas se establecerán:",
