      "c": "Alto Representante de la Unión para Asuntos de Exteriores y Política de Seguridad, Parlamento Europeo, Consejo Europeo, Comisión Europea, Consejo, Tribunal de Justicia de la Unión Europea, Tribunal de Cuentas y Banco Central Europeo.",
