      "d": "Sí, pero sólo los nacionales de Estados Miembros de la Unión Europea y del Espacio Económico Europeo. sus cónyuges y descendientes, y las personas extracomunitarias de forma excepcional en profesiones sanitarias o que impliquen participación en el ejercicio del poder público."
